//! `.isoloom/.gitignore`: what the tools a runner starts write beside the generated files, kept
//! out of version control. It goes with every target, like the resolved snapshot, so a project
//! that commits its generated files never commits a Terraform state (which holds the secrets
//! Terraform saw), a provider cache, or a Vagrant machine folder.
//!
//! `.terraform.lock.hcl` is left out on purpose: it records the checksums of the provider builds
//! `terraform init` chose, so a project that commits its generated files commits it too, and
//! every machine then installs the same providers.

use isoloom_render::GeneratedFile;
use isoloom_render::secrets::REACH_DIR;

/// Where it is written, relative to the project folder.
pub const PATH: &str = ".isoloom/.gitignore";

/// The patterns, each group under the comment that says whose files they are.
fn sections() -> [(&'static str, Vec<String>); 3] {
    let owned = |patterns: &[&str]| patterns.iter().map(|p| (*p).to_owned()).collect();
    [
        (
            "Terraform: the provider cache, the state and its backups (secrets in plain text), the state's lock, crash logs.",
            owned(&[
                ".terraform/",
                "*.tfstate",
                "*.tfstate.*",
                ".terraform.tfstate.lock.info",
                "crash.log",
                "crash.*.log",
            ]),
        ),
        ("Vagrant: each machine's folder (its id, its private key).", owned(&[".vagrant/"])),
        (
            "The runner: each cloud machine's SSH login, written as Terraform reaches it.",
            vec![format!("{REACH_DIR}/")],
        ),
    ]
}

/// The file.
pub(crate) fn file() -> GeneratedFile {
    let mut contents = String::from("# Generated by isoloom: what the tools write beside the generated files. Don't edit.\n");
    for (why, patterns) in sections() {
        contents.push_str("\n# ");
        contents.push_str(why);
        contents.push('\n');
        for pattern in patterns {
            contents.push_str(&pattern);
            contents.push('\n');
        }
    }
    GeneratedFile {
        path: PATH.to_owned(),
        contents,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Whether `name` matches `glob`, whose only wildcard is `*`.
    fn matches(glob: &str, name: &str) -> bool {
        let parts: Vec<&str> = glob.split('*').collect();
        let (Some(first), Some(last)) = (parts.first(), parts.last()) else {
            return false;
        };
        let Some(mut rest) = name.strip_prefix(first) else { return false };
        if parts.len() == 1 {
            return rest.is_empty();
        }
        for middle in &parts[1..parts.len() - 1] {
            match rest.split_once(middle) {
                Some((_, after)) => rest = after,
                None => return false,
            }
        }
        rest.len() >= last.len() && rest.ends_with(last)
    }

    /// Whether `.gitignore` text ignores `path` (a folder ends with `/`) by its last name.
    fn ignores(text: &str, path: &str) -> bool {
        let name = path.trim_end_matches('/').rsplit('/').next().unwrap_or(path);
        text.lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .any(|pattern| match pattern.strip_suffix('/') {
                Some(folder) => path.ends_with('/') && matches(folder, name),
                None => matches(pattern, name),
            })
    }

    #[test]
    fn the_tools_state_is_ignored_and_the_lock_file_is_not() {
        let text = file().contents;
        for path in [
            "cloud-vm/aws/.terraform/",
            "cloud-vm/aws/terraform.tfstate",
            "cloud-vm/aws/terraform.tfstate.backup",
            "proxmox/.terraform.tfstate.lock.info",
            "esxi/crash.log",
            "vagrant/.vagrant/",
            "cloud-vm/aws/.isoloom-reach/",
        ] {
            assert!(ignores(&text, path), "{path}:\n{text}");
        }
        for path in [
            "cloud-vm/aws/.terraform.lock.hcl",
            "cloud-vm/aws/main.tf",
            "docker/compose.yml",
            "docker/run.json",
        ] {
            assert!(!ignores(&text, path), "{path}:\n{text}");
        }
    }
}
